const now = new Date();
const out = [];
for (let i = 0; i < 2; i++) {
  const d = new Date(now.getTime() - i * 86400000);
  const y = d.getUTCFullYear();
  const mo = d.getUTCMonth() + 1;
  const day = d.getUTCDate();
  const q = Math.floor((mo - 1) / 3) + 1;
  const mm = mo < 10 ? "0" + mo : "" + mo;
  const dd = day < 10 ? "0" + day : "" + day;
  const stamp = "" + y + mm + dd;
  out.push({ json: { url: "https://www.sec.gov/Archives/edgar/daily-index/" + y + "/QTR" + q + "/form." + stamp + ".idx", dateStamp: stamp, which: i === 0 ? "today" : "yesterday" } });
}
return out;

const NL = String.fromCharCode(10);
const CR = String.fromCharCode(13);
const want = { "10-K": 62, "10-K/A": 45, "10-Q": 56, "10-Q/A": 45 };
const items = $input.all();
const found = {};
const order = [];
const readOk = [];
for (let i = 0; i < items.length; i++) {
  const j = items[i].json;
  let text = null;
  if (typeof j.data === "string") { text = j.data; } else if (typeof j.body === "string") { text = j.body; }
  if (!text) { continue; }
  if (text.indexOf("edgar/data/") === -1) { continue; }
  readOk.push(i);
  const lines = text.split(NL);
  for (let k = 0; k < lines.length; k++) {
    const line = lines[k].split(CR).join("");
    if (line.length < 40) { continue; }
    const form = line.substring(0, 17).trim();
    if (want[form] === undefined) { continue; }
    const rest = line.substring(17);
    const parts = rest.split(" ").filter(function (s) { return s.length > 0; });
    if (parts.length < 4) { continue; }
    const fileName = parts[parts.length - 1];
    const dateFiled = parts[parts.length - 2];
    const cikStr = parts[parts.length - 3];
    if (fileName.indexOf("edgar/") !== 0) { continue; }
    if (dateFiled.length !== 8 || !isFinite(Number(dateFiled))) { continue; }
    const cik = Number(cikStr);
    if (!isFinite(cik) || cik <= 0) { continue; }
    const company = parts.slice(0, parts.length - 3).join(" ").trim();
    if (!company) { continue; }
    const base = fileName.substring(fileName.lastIndexOf("/") + 1);
    const accn = base.split(".txt").join("");
    const noDash = accn.split("-").join("");
    if (found[accn]) { continue; }
    const filed = dateFiled.substring(0, 4) + "-" + dateFiled.substring(4, 6) + "-" + dateFiled.substring(6, 8);
    found[accn] = { form: form, company: company, cik: cik, accn: accn, filed: filed, url: "https://www.sec.gov/Archives/edgar/data/" + cik + "/" + noDash + "/" + accn + "-index.htm", score: want[form] };
    order.push(accn);
  }
}
const store = $getWorkflowStaticData("global");
if (!store.seenAccessions) { store.seenAccessions = []; }
const seen = {};
for (let i = 0; i < store.seenAccessions.length; i++) { seen[store.seenAccessions[i]] = true; }
const fresh = [];
for (let i = 0; i < order.length; i++) {
  if (seen[order[i]]) { continue; }
  fresh.push(found[order[i]]);
}
fresh.sort(function (x, y) {
  if (x.filed === y.filed) { return 0; }
  return x.filed < y.filed ? 1 : -1;
});
const take = fresh.slice(0, 60);
if (!take.length) { return []; }
const rows = take.map(function (f) {
  return { kind: "filing", headline: f.company + " filed a " + f.form, detail: f.company + " (CIK " + f.cik + ") filed form " + f.form + " with the SEC on " + f.filed + ". Accession " + f.accn + ". Seen in the EDGAR daily form index.", url: f.url, source: "SEC EDGAR", tickers: [], industries: [], score: f.score };
});
const accns = take.map(function (f) { return f.accn; });
store.seenAccessions = store.seenAccessions.concat(accns).slice(-5000);
return [{ json: { body: { p_token: "<<IRIS_TOKEN>>", p_rows: rows }, filingCount: rows.length, indexesParsed: readOk.length, candidatesFound: order.length, alreadySeen: order.length - fresh.length } }];
